import{_ as l,a0 as s,w as p,s as d,ao as o,I as i,a1 as e,A as a,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"保護你的Linux系統的九個老生常談 | LCTT x X-CMD","titleTemplate":false,"description":"保護你的Linux系統的九個老生常談 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"保護你的Linux系統的九個老生常談 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"保護你的Linux系統的九個老生常談 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140617 9 Good Ways To Protect Your Linux System","title":"保護你的Linux系統的九個老生常談","tag":"201407","desc":""},"relativePath":"201407/20140617 9 Good Ways To Protect Your Linux System.md","filePath":"[post].md"}'),u={name:"201407/20140617 9 Good Ways To Protect Your Linux System.md"};function x(m,t,f,g,T,k){const r=s("Link");return p(),d("div",null,[t[25]||(t[25]=o('<h1 id="保護你的linux系統的九個老生常談" tabindex="-1">保護你的Linux系統的九個老生常談 <a class="header-anchor" href="#保護你的linux系統的九個老生常談" aria-label="Permalink to “保護你的Linux系統的九個老生常談”">​</a></h1><p>在現在這個世道中，保障基於Linux的系統的安全是十分重要的。但是，你得知道怎麼幹。一個簡單反惡意程序軟件是遠遠不夠的，你需要採取其它措施來協同工作。那麼試試下面這些手段吧。</p><p><img src="http://www.efytimes.com/admin/useradmin/photo/2Rak10143PM6172014.jpeg" alt=""></p><h3 id="_1-使用selinux" tabindex="-1">1. 使用SELinux <a class="header-anchor" href="#_1-使用selinux" aria-label="Permalink to “1. 使用SELinux”">​</a></h3>',4)),i("p",null,[e(r,{href:"http://selinuxproject.org/page/Main_Page"},{default:a(()=>[...t[0]||(t[0]=[n("SELinux",-1)])]),_:1}),t[1]||(t[1]=n("是用來對Linux進行安全加固的，有了它，用户和管理員們就可以對訪問控制進行更多控制。SELinux為訪問控制添加了更細的顆粒度控制。與僅可以指定誰可以讀、寫或執行一個文件的權限不同的是，SELinux可以讓你指定誰可以刪除鏈接、只能追加、移動一個文件之類的更多控制。（LCTT譯註：雖然NSA也給SELinux貢獻過很多代碼，但是目前尚無證據證明SELinux有潛在後門）",-1))]),t[26]||(t[26]=i("h3",{id:"_2-訂閲漏洞警報服務",tabindex:"-1"},[n("2. 訂閲漏洞警報服務 "),i("a",{class:"header-anchor",href:"#_2-訂閲漏洞警報服務","aria-label":"Permalink to “2. 訂閲漏洞警報服務”"},"​")],-1)),i("p",null,[t[3]||(t[3]=n("安全缺陷不一定是在你的操作系統上。事實上，漏洞多見於安裝的應用程序之中。為了避免這個問題的發生，你必須保持你的應用程序更新到最新版本。此外，訂閲漏洞警報服務，如",-1)),e(r,{href:"http://www.securityfocus.com/rss/vulnerabilities.xml"},{default:a(()=>[...t[2]||(t[2]=[n("SecurityFocus",-1)])]),_:1}),t[4]||(t[4]=n("。",-1))]),t[27]||(t[27]=o('<h3 id="_3-禁用不用的服務和應用" tabindex="-1">3. 禁用不用的服務和應用 <a class="header-anchor" href="#_3-禁用不用的服務和應用" aria-label="Permalink to “3. 禁用不用的服務和應用”">​</a></h3><p>通常來講，用户大多數時候都用不到他們系統上的服務和應用的一半。然而，這些服務和應用還是會運行，這會招來攻擊者。因而，最好是把這些不用的服務停掉。（LCTT譯註：或者乾脆不安裝那些用不到的服務，這樣根本就不用關注它們是否有安全漏洞和該升級了。）</p><h3 id="_4-檢查系統日誌" tabindex="-1">4. 檢查系統日誌 <a class="header-anchor" href="#_4-檢查系統日誌" aria-label="Permalink to “4. 檢查系統日誌”">​</a></h3><p>你的系統日誌告訴你在系統上發生了什麼活動，包括攻擊者是否成功進入或試着訪問系統。時刻保持警惕，這是你第一條防線，而經常性地監控系統日誌就是為了守好這道防線。</p><h3 id="_5-考慮使用端口試探" tabindex="-1">5. 考慮使用端口試探 <a class="header-anchor" href="#_5-考慮使用端口試探" aria-label="Permalink to “5. 考慮使用端口試探”">​</a></h3>',5)),i("p",null,[t[6]||(t[6]=n("設置",-1)),e(r,{href:"http://en.wikipedia.org/wiki/Port_knocking"},{default:a(()=>[...t[5]||(t[5]=[n("端口試探（Port knocking）",-1)])]),_:1}),t[7]||(t[7]=n("是建立服務器安全連接的好方法。一般做法是發生特定的包給服務器，以觸發服務器的回應/連接（打開防火牆）。端口敲門對於那些有開放端口的系統是一個很好的防護措施。",-1))]),i("p",null,[t[9]||(t[9]=n("下面是來自 ",-1)),e(r,{href:"http://www.portknocking.org/"},{default:a(()=>[...t[8]||(t[8]=[n("http://www.portknocking.org/",-1)])]),_:1}),t[10]||(t[10]=n(" 的示意圖：",-1))]),t[28]||(t[28]=o('<p><img src="http://www.portknocking.org/images/portknocking-explained-01.png" alt=""><img src="http://www.portknocking.org/images/portknocking-explained-02.png" alt=""><img src="http://www.portknocking.org/images/portknocking-explained-03.png" alt=""><img src="http://www.portknocking.org/images/portknocking-explained-04.png" alt=""></p><h3 id="_6-使用iptables" tabindex="-1">6. 使用Iptables <a class="header-anchor" href="#_6-使用iptables" aria-label="Permalink to “6. 使用Iptables”">​</a></h3><p>Iptables是什麼？這是一個應用框架，它允許用户自己為系統建立一個強大的防火牆。因此，要提升安全防護能力，就要學習怎樣一個好的防火牆以及怎樣使用Iptables框架。</p><h3 id="_7-默認拒絕所有" tabindex="-1">7. 默認拒絕所有 <a class="header-anchor" href="#_7-默認拒絕所有" aria-label="Permalink to “7. 默認拒絕所有”">​</a></h3><p>防火牆有兩種思路：一個是允許每一點通信，另一個是拒絕所有訪問，提示你是否許可。第二種更好一些。你應該只允許那些重要的通信進入。（LCTT譯註：即默認許可策略和默認禁止策略，前者你需要指定哪些應該禁止，除此之外統統放行；後者你需要指定哪些可以放行，除此之外全部禁止。）</p><h3 id="_8-使用入侵檢測系統" tabindex="-1">8. 使用入侵檢測系統 <a class="header-anchor" href="#_8-使用入侵檢測系統" aria-label="Permalink to “8. 使用入侵檢測系統”">​</a></h3>',6)),i("p",null,[t[12]||(t[12]=n("入侵檢測系統，或者叫IDS，允許你更好地管理系統上的通信和受到的攻擊。",-1)),e(r,{href:"http://www.snort.org/"},{default:a(()=>[...t[11]||(t[11]=[n("Snort",-1)])]),_:1}),t[13]||(t[13]=n("是目前公認的Linux上的最好的IDS。",-1))]),t[29]||(t[29]=i("h3",{id:"_9-使用全盤加密",tabindex:"-1"},[n("9. 使用全盤加密 "),i("a",{class:"header-anchor",href:"#_9-使用全盤加密","aria-label":"Permalink to “9. 使用全盤加密”"},"​")],-1)),t[30]||(t[30]=i("p",null,"加密的數據更難竊取，有時候根本不可能被竊取，這就是你應該對整個驅動器加密的原因。採用這種方式後，如果有某個人進入到你的系統，那麼他看到這些加密的數據後，就有得頭痛了。根據一些報告，大多數數據丟失源於機器被盜。",-1)),t[31]||(t[31]=i("hr",null,null,-1)),i("p",null,[t[15]||(t[15]=n("via: ",-1)),e(r,{href:"http://www.efytimes.com/e1/fullnews.asp?edid=141368"},{default:a(()=>[...t[14]||(t[14]=[n("http://www.efytimes.com/e1/fullnews.asp?edid=141368",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=n("譯者：",-1)),e(r,{href:"https://github.com/GOLinux"},{default:a(()=>[...t[16]||(t[16]=[n("GOLinux",-1)])]),_:1}),t[19]||(t[19]=n(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:a(()=>[...t[17]||(t[17]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[22]||(t[22]=n("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[20]||(t[20]=[n("LCTT",-1)])]),_:1}),t[23]||(t[23]=n(" 原創翻譯，",-1)),e(r,{href:"http://linux.cn/"},{default:a(()=>[...t[21]||(t[21]=[n("Linux中國",-1)])]),_:1}),t[24]||(t[24]=n(" 榮譽推出",-1))])])}const P=l(u,[["render",x]]);export{b as __pageData,P as default};
